'use strict';
const G=window.CantinaGame,$=id=>document.getElementById(id);
let s=G.fresh(),active=false,storage=null;try{storage=localStorage;}catch{}
const store=window.CantinaSave.create({storage,locks:navigator.locks,validSave:G.validSave,onBlocked:reason=>{active=false;document.querySelector('main').inert=true;$('tab-message').textContent=reason;document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('tab-dialog').showModal();}});
let previousStage=-1,previousMobile=null,previousReq='',shownLogs=new Set(),last=performance.now(),saveElapsed=0,lastHunt=0;
const fmt=n=>Math.floor(n).toLocaleString('en-US'),money=n=>'$'+(Math.abs(n)>=1e6?(n/1e6).toFixed(2)+'M':Math.abs(n)>=1e4?Math.floor(n/1000)+'k':fmt(n)),date=n=>new Date(Date.UTC(2026,0,1)+n*86400000).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
function save(){if(!active||!store.isOwner)return;$('save-status').textContent=store.save(s)?'Saved on this device.':'Browser storage unavailable. Keep this tab open to retain progress.';}
function showCashNotice(){if(active&&s.cashNotice&&!document.querySelector('dialog[open]'))$('cash-dialog').showModal();}
async function openSession(){const loaded=await store.acquire();if(loaded===undefined||!store.isOwner)return;s={...G.fresh(),...(loaded||{})};active=true;document.querySelector('main').inert=false;document.querySelectorAll('dialog[open]').forEach(d=>d.close());previousStage=-1;previousReq='';shownLogs.clear();$('log').replaceChildren();last=performance.now();saveElapsed=0;render();if(!s.started)$('welcome').showModal();else if(s.needsIntro)stageIntro();else showCashNotice();save();}
const controlInfo={engineers:['engineer-controls','security engineers'],compute:['compute-controls','compute'],researchers:['research-controls','AI researchers'],marketers:['marketing-controls','marketers']};
for(const [key,[id,name]] of Object.entries(controlInfo))$(id).innerHTML=`<div class="allocation"><button data-adjust="${key}" data-delta="-1" aria-label="Reduce ${name}">▼</button><div class="middle"><strong id="${key}-spend"></strong><small id="${key}-count"></small></div><button class="increase" data-adjust="${key}" data-delta="1" aria-label="Increase ${name}">▲</button><span class="delta decrease" id="${key}-decrease"></span><span class="delta increase" id="${key}-increase"></span><span class="hint" id="${key}-hint"></span></div>`;
const layouts=[
 {human:[28,15,36,108],compute:[77,15,36,108],findings:[53,43,36,82],valids:[53,60,36,103]},
 {budget:[50,10,56,80],human:[28,34,36,136],compute:[77,34,36,108],findings:[53,60,36,82],valids:[53,79,36,105]},
 {budget:[50,9,57,80],human:[24,31,36,136],compute:[76,31,36,136],researchers:[24,58,36,136],harness:[24,81,36,100],findings:[76,58,36,95],valids:[76,81,36,110]},
 {budget:[50,9,58,78],human:[18,32,29,132],researchers:[50,32,29,132],compute:[82,32,29,132],marketers:[18,57,29,132],harness:[50,57,29,92],findings:[82,57,29,92],publicity:[18,81,29,96],valids:[82,81,29,112]}
];
function layout(){const mobile=innerWidth<=960;if(previousStage===s.stage&&previousMobile===mobile)return;previousStage=s.stage;previousMobile=mobile;const pos=structuredClone(layouts[s.stage]);if(mobile){if(s.stage<2){pos.human[2]=42;pos.human[0]=25;pos.compute[2]=42;pos.compute[0]=75;pos.findings[2]=48;pos.valids[2]=48;if(pos.budget)pos.budget[2]=75;}else if(s.stage===2){for(const [id,p] of Object.entries(pos)){if(id==='budget')p[2]=82;else{p[0]=p[0]<50?25:75;p[2]=44;}}}else{Object.assign(pos,{budget:[50,7,83,78],human:[25,25,44,132],compute:[75,25,44,132],researchers:[25,44,44,132],harness:[25,61,44,92],findings:[75,44,44,92],valids:[75,61,44,105],marketers:[25,82,44,132],publicity:[75,82,44,95]});}}
 $('board').className='board stage-'+s.stage;
 for(const id of ['budget','human','compute','researchers','harness','findings','valids','marketers','publicity']){const p=pos[id];$(id).hidden=!p||(s.stage===0&&s.found===0&&['findings','valids'].includes(id));if(p){$(id).style.left=p[0]+'%';$(id).style.top=p[1]+'%';$(id).style.width=p[2]+'%';$(id).style.minHeight=p[3]+'px';}}
 const edges=s.stage===0?[['human','findings'],['compute','findings'],['findings','valids']]:s.stage===1?[['budget','human'],['human','valids'],['compute','findings'],['findings','valids']]:s.stage===2?[['budget','human'],['budget','compute'],['human','valids'],['compute','findings'],['researchers','harness'],['harness','findings'],['findings','valids']]:[['budget','human'],['budget','researchers'],['budget','compute'],['researchers','harness'],['harness','findings'],['compute','findings'],['human','valids'],['findings','valids'],['marketers','publicity']];
 const boardHeight=$('board').clientHeight;let paths='';for(const [from,to] of edges){const a=pos[from],b=pos[to];if(!a||!b)continue;const sameRow=Math.abs(a[1]-b[1])<3;let x1=a[0]*10,y1=a[1]*8+a[3]/boardHeight*400,x2=b[0]*10,y2=b[1]*8-b[3]/boardHeight*400;
 if(from==='human'&&s.stage>=1){x1=(a[0]+a[2]/2)*10;y1=a[1]*8;x2=(b[0]-b[2]/2)*10;y2=b[1]*8;const middle=(x1+x2)/2;paths+=`<path d="M${x1},${y1} H${middle} V${y2} H${x2}"/>`;}
 else if(sameRow||from==='harness'&&to==='findings'){x1=(a[0]+a[2]/2)*10;y1=a[1]*8;x2=(b[0]-b[2]/2)*10;y2=b[1]*8;const mid=(x1+x2)/2;paths+=`<path d="M${x1},${y1} H${mid} V${y2} H${x2}"/>`;}
 else{const mid=(y1+y2)/2;paths+=`<path d="M${x1},${y1} V${mid} H${x2} V${y2}"/>`;}}
 $('paths').innerHTML=paths;
}
function render(){const a=G.stats(s);layout();$('board').classList.toggle('is-paused',s.paused||s.ready);$('paths').style.opacity=s.stage===0&&s.found===0?'0':'1';if(s.stage===0&&s.found>0){$('findings').hidden=false;$('valids').hidden=false;}
 $('human-title').textContent=s.stage===0?'SECURITY RESEARCHER':'SECURITY ENGINEERS';$('hunt').hidden=s.stage!==0;$('hunt').disabled=s.ready||s.paused||!s.started;$('engineer-controls').hidden=s.stage===0;$('compute-controls').hidden=s.stage<2;$('compute-fixed').hidden=s.stage>=2;
 $('cash').textContent=money(s.cash);$('net').textContent=(a.net<0?'−':'+')+money(Math.abs(a.net));$('net').className=a.net<0?'negative':'positive';$('runway-wrap').hidden=a.net>=0;$('runway').textContent=fmt(s.cash/Math.max(1,-a.net))+' mo';
 for(const [key]of Object.entries(controlInfo)){$(key+'-spend').textContent=money(G.budget(s,key))+'/mo';$(key+'-count').textContent=key==='compute'?s.compute+' GPU'+(s.compute===1?'':'s'):s[key]+' '+(s[key]===1?'person':'people');$(key+'-hint').textContent='Next: +'+money(G.budget({...s,[key]:s[key]+1},key)-G.budget(s,key))+'/mo';for(const [direction,suffix] of [[-1,'decrease'],[1,'increase']]){const value=G.marginal(s,key,direction),el=$(key+'-'+suffix),label=G.marginalLabels[key];el.textContent=value===null?'—':(Math.abs(value)<.005?'0.00%':(value>0?'+':'−')+Math.abs(value).toFixed(2)+'%');el.title='Change in '+label;el.setAttribute('aria-label',el.textContent+' '+label);const button=document.querySelector(`[data-adjust="${key}"][data-delta="${direction}"]`);button.setAttribute('aria-describedby',el.id);button.title=el.textContent+' '+label;}document.querySelector(`[data-adjust="${key}"][data-delta="-1"]`).disabled=s[key]<=(key==='compute'?1:0)||s.ready||s.won;document.querySelector(`[data-adjust="${key}"][data-delta="1"]`).disabled=!G.canIncrease(s,key)||s.ready||s.won;}
 $('harness-value').textContent=s.harness.toFixed(2)+'×';$('harness-rate').textContent='+'+(a.research*30).toFixed(2)+'× / month';$('found').textContent=fmt(s.found);$('discovery-rate').textContent=s.stage===0?'potential vulnerabilities':a.discovery.toFixed(1)+' / day · '+fmt(s.queue)+' in queue';$('valid').textContent=fmt(s.valid);$('fp').textContent=(a.fp*100).toFixed(1)+'% false positives';$('criticals').hidden=s.stage<2&&s.critical===0;$('criticals').textContent=fmt(s.critical)+' critical'+(s.critical===1?'':'s');$('publicity-value').textContent=Math.floor(s.publicity)+'/100';$('bounty').textContent=money(a.bounty)+' / valid bug';
 for(const id of ['human','compute','researchers','marketers'])$(id).classList.remove('focus');const focus=s.stage===0?'human':s.stage===1&&s.engineers<2?'human':s.stage>=2&&s.researchers===0?'researchers':s.stage>=3&&s.marketers===0?'marketers':a.discovery>a.capacity?'human':'compute';if(!s.ready&&!s.won&&!(s.stage===1&&s.engineers>=2))$(focus).classList.add('focus');$('board-caption').textContent=s.ready?'Milestone reached.':s.stage===0?'Start with one finding.':s.won?'Security at scale.':s.stage===1&&s.engineers>=2?'Your team is validating findings.':'Highlighted inputs need attention.';
 $('play').textContent=s.paused?'▶':'Ⅱ';$('play').setAttribute('aria-label',s.paused?'Play':'Pause');$('play').disabled=s.ready||s.won||!s.started;$('status').textContent=s.won?'COMPLETE':'PAUSED';$('status').className=!s.paused&&!s.ready?'running':'';$('date').textContent=date(s.time);document.querySelectorAll('[data-speed]').forEach(b=>{b.classList.toggle('active',+b.dataset.speed===s.speed);b.setAttribute('aria-pressed',String(+b.dataset.speed===s.speed));b.disabled=s.ready||s.won||!s.started;});
 const m=G.stages[s.stage];$('milestone-name').textContent=m.name;$('reward').textContent=s.ready||s.won?'COMPLETE':m.reward?'+'+money(m.reward):'';const sig=s.stage+':'+s.won;if(sig!==previousReq){previousReq=sig;$('requirements').innerHTML=m.requirements.map(([text],i)=>`<div class="requirement" id="req-${i}"><div class="row"><span class="check">○</span><span>${text}</span></div><div class="track"><div class="fill"></div></div></div>`).join('');}m.requirements.forEach(([,f],i)=>{const p=Math.min(1,f(s)),el=$('req-'+i);el.classList.toggle('done',p>=1);el.querySelector('.check').textContent=p>=1?'✓':'○';el.querySelector('.fill').style.width=p*100+'%';});$('claim').hidden=!s.ready||s.won;$('claim').textContent=m.action+(m.reward?'  +'+money(m.reward):'');
 const log=$('log'),nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<50;for(const e of s.log){if(shownLogs.has(e.id))continue;shownLogs.add(e.id);const p=document.createElement('p');p.className='entry';p.dataset.id=e.id;const time=document.createElement('time');time.textContent=date(e.time);p.append(time,document.createTextNode(e.text));log.append(p);}while(log.children.length>60)log.firstElementChild.remove();if(nearBottom)log.scrollTop=log.scrollHeight;
}
function stageIntro(){s.needsIntro=true;s.paused=true;const m=G.stages[s.stage];$('stage-number').textContent='STAGE '+(s.stage+1);$('stage-title').textContent=m.title;$('stage-intro').textContent=m.intro;$('stage-dialog').showModal();save();}
$('enter').onclick=()=>{s.started=true;$('welcome').close();render();stageIntro();};$('continue').onclick=()=>{s.needsIntro=false;s.paused=false;$('stage-dialog').close();save();render();};$('stage-dialog').addEventListener('cancel',e=>e.preventDefault());$('welcome').addEventListener('cancel',e=>e.preventDefault());
$('hunt').onclick=()=>{const now=performance.now();if(now-lastHunt<100)return;lastHunt=now;G.hunt(s);save();render();};
document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{G.adjust(s,b.dataset.adjust,+b.dataset.delta);save();render();});
$('play').onclick=()=>{s.paused=!s.paused;save();render();};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{s.speed=+b.dataset.speed;save();render();});
$('claim').onclick=()=>{if(!G.claim(s))return;save();render();if(s.won){$('win-summary').textContent=`${fmt(s.valid)} validated bugs. ${fmt(s.critical)} criticals. ${(G.stats(s).fp*100).toFixed(1)}% false positives. All four milestones complete.`;$('win-dialog').showModal();}else stageIntro();};
const explanations={net:['Cash and monthly budget','Valid bugs earn bounties; criticals pay five times as much. Net is your estimated monthly bounty revenue minus payroll and GPU rentals. Scaling raises costs per hire or GPU. To increase a budget, cash must cover one month of total costs. If cash runs out, the game pauses and keeps your team. Reduce budgets before resuming, or explicitly choose to cancel paid budgets and continue solo. Your own reviews and original GPU can then rebuild cash.'],harness:['Apex harness','AI researchers improve the harness continuously. A better harness finds more bugs per GPU and lowers the false positive rate. Returns diminish as the harness improves.'],findings:['Findings','Compute produces potential bugs. Findings wait in the review queue until your security engineers can validate them. More GPUs also increase the share of criticals among validated bugs.'],valids:['Validated bugs','Only real bugs earn bounties. Engineers process more findings and improve the projected false positive rate—the share of findings expected to be rejected. These are simulated outcomes, not real scans.'],publicity:['Publicity','Marketers grow publicity over time. Growth slows as publicity rises. A stronger reputation attracts higher-value work and increases the bounty paid for each valid bug.']};
document.querySelectorAll('[data-explain]').forEach(b=>b.onclick=()=>{const [title,text]=explanations[b.dataset.explain];$('explain-title').textContent=title;$('explain-text').textContent=text;$('explanation').showModal();});$('settings').onclick=()=>$('settings-dialog').showModal();$('restart').onclick=()=>$('reset-dialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('confirm-reset').onclick=()=>{s=G.fresh();s.started=true;shownLogs.clear();$('log').replaceChildren();previousStage=-1;$('reset-dialog').close();render();stageIntro();};
$('cash-review').onclick=()=>{s.cashNotice=false;$('cash-dialog').close();save();render();};
$('cash-solo').onclick=()=>{if(!G.continueSolo(s))return;$('cash-dialog').close();last=performance.now();save();render();};
$('cash-dialog').addEventListener('cancel',e=>e.preventDefault());$('tab-dialog').addEventListener('cancel',e=>e.preventDefault());
$('tab-retry').onclick=()=>openSession();
window.addEventListener('resize',()=>{previousStage=-1;layout();});
window.addEventListener('pagehide',()=>{save();active=false;document.querySelector('main').inert=true;store.release();});
window.addEventListener('pageshow',e=>{if(e.persisted)openSession();});
document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)save();});
setInterval(()=>{const now=performance.now(),elapsed=Math.min((now-last)/1000,1);last=now;if(!active||!store.isOwner)return;const notice=s.cashNotice;if(!document.querySelector('dialog[open]'))G.step(s,elapsed*s.speed);render();showCashNotice();saveElapsed+=elapsed;if(saveElapsed>2||s.cashNotice&&!notice){saveElapsed=0;save();}},200);
render();openSession();
